  "implementation": "import math

def solve(case):
    matrix = case['matrix']
    idf = case['idf']
    vector = case['vector']
    n_rows = len(matrix)
    if n_rows == 0:
        raise ValueError('Empty matrix')
    n_cols = len(idf)
    for row in matrix:
        if len(row) != n_cols:
            raise ValueError('Invalid row length')
    if len(vector) != n_rows:
        raise ValueError('Vector length mismatch')
    epsilon = 1e-12
    degrees = []
    for i in range(n_rows):
        s = 0.0
        row = matrix[i]
        for j in range(n_cols):
            val = row[j] * idf[j]
            s += val * val
        degrees.append(max(s, epsilon))
    sqrt_deg = [math.sqrt(d) for d in degrees]
    scaled_v = [vector[i] / sqrt_deg[i] for i in range(n_rows)]
    z = [0.0] * n_cols
    for i in range(n_rows):
        row = matrix[i]
        svi = scaled_v[i]
        for j in range(n_cols):
            z[j] += row[j] * idf[j] * svi
    w = [0.0] * n_rows
    for i in range(n_rows):
        row = matrix[i]
        total = 0.0
        for j in range(n_cols):
            total += row[j] * idf[j] * z[j]
        w[i] = total
    result = [w[i] / sqrt_deg[i] for i in range(n_rows)]
    return {'degree': degrees, 'result': result}
